// Matters visual baselines (#394): every viewport × theme project (360/768/1280, light and dark)
// with the clock frozen: the list, the overview, the conflict card, the proceedings tab (appeal
// chain with W.M.P. children), people, documents, the Tamil and Kannada rows, and the empty and
// error states. The relative "in N days" text follows the server's real clock, so it is masked.
// Baselines live in e2e/__screenshots__ and are only ever generated by the e2e workflow's
// `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md); without one the
// test is skipped.
import { existsSync } from 'node:fs';

import type { Locator, Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { MATTERS, MATTERS_WORKSPACE } from '../../fixtures/matters-data.ts';
import { expect, test } from '../../fixtures/index.ts';

import {
  emptyMatters,
  listLayout,
  matterPath,
  mattersPath,
  openMatters,
  volatile,
} from './helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

interface Shot {
  name: string;
  /** `database` is the worker database. Returns the element to shoot, or the page. */
  setUp: (page: Page, asUser: AsUser, database: string) => Promise<Locator | null>;
}

const open =
  (path: string, ready: (page: Page) => Locator): Shot['setUp'] =>
  async (page, asUser) => {
    await openMatters(page, asUser, { path });
    await expect(ready(page).first()).toBeVisible();
    return null;
  };

const SHOTS: readonly Shot[] = [
  {
    name: 'matters-list.png',
    setUp: open(mattersPath(), (page) => listLayout(page).locator('[data-matter-row]')),
  },
  {
    name: 'matters-overview.png',
    setUp: open(matterPath(MATTERS.appeal), (page) => page.locator('[data-slot="next-date-card"]')),
  },
  {
    name: 'matters-conflict-card.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser, { path: matterPath(MATTERS.conflict) });
      const card = page.locator('[data-slot="date-conflict-card"]');
      // The first run matched two cards for one conflict (server-rendered `_r_` and client `_R_`
      // ids) while the page re-rendered; the settled page has one. Wait for it so the shot is strict.
      await expect(card).toHaveCount(1);
      return card;
    },
  },
  {
    name: 'matters-proceedings.png',
    setUp: open(matterPath(MATTERS.appeal, 'proceedings'), (page) => page.getByRole('tree')),
  },
  {
    name: 'matters-people.png',
    setUp: open(matterPath(MATTERS.appeal, 'people'), (page) => page.locator('[data-people]')),
  },
  {
    name: 'matters-documents.png',
    setUp: open(matterPath(MATTERS.appeal, 'documents'), (page) =>
      page.locator('[data-documents]'),
    ),
  },
  {
    name: 'matters-empty.png',
    setUp: async (page, asUser, database) => {
      await emptyMatters(database);
      await openMatters(page, asUser);
      await expect(page.locator('main [data-pattern-state="empty"]')).toBeVisible();
      return null;
    },
  },
  {
    name: 'matters-error.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser);
      await page.goto(`/w/${MATTERS_WORKSPACE}/matters?__state=error`);
      await expect(page.locator('main [data-pattern-state="error"]')).toBeVisible({
        timeout: 15_000,
      });
      return null;
    },
  },
];

test.describe('matters visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        const target = await shot.setUp(page, asUser, db.name);
        const options = { animations: 'disabled', caret: 'hide', mask: volatile(page) } as const;
        if (target === null) await expect(page).toHaveScreenshot(shot.name, options);
        else await expect(target).toHaveScreenshot(shot.name, options);
      },
    );
  }
});
